INSERT INTO reviews (review_id, merchant_id, user_id, rating, body, image_captions, created_at) VALUES ('rv_anchor_001', 'merchant_cs_training_anchor', 'rvu_98233', 2, '考前发的所谓密卷，和公开的模拟题重合度很高，说是内部真题站不住脚。花了 595 元，感觉还能接受。', '[]', '2025-07-19T22:47:00+08:00');
