INSERT INTO reviews (review_id, merchant_id, user_id, rating, body, image_captions, created_at) VALUES ('rv_anchor_004', 'merchant_cs_training_anchor', 'rvu_32824', 2, '宣传押题和高通过率，但资料来源说不清楚，客服只说是内部渠道，建议谨慎。从学校过去地铁 8 站，步行还要 6 分钟。', '[]', '2025-07-18T17:58:05+08:00');
