INSERT INTO reviews (review_id, merchant_id, user_id, rating, body, image_captions, created_at) VALUES ('rv_anchor_006', 'merchant_cs_training_anchor', 'rvu_46658', 2, '冲着「协议进面」报的，签约时才发现退费要扣课时费和资料费，实际能退的很少。从学校过去地铁 6 站，步行还要 11 分钟。', '[]', '2025-07-18T07:11:12+08:00');
