INSERT INTO reviews (review_id, merchant_id, user_id, rating, body, image_captions, created_at) VALUES ('rv_anchor_008', 'merchant_cs_training_anchor', 'rvu_40305', 3, '主讲老师的申论批改确实认真，逐段评语给得很细，这部分物有所值。第 3 次模考排到第 189 名。', '[]', '2025-07-21T20:14:00+08:00');
INSERT INTO reviews (review_id, merchant_id, user_id, rating, body, image_captions, created_at) VALUES ('rv_anchor_009', 'merchant_cs_training_anchor', 'rvu_94135', 4, '课程本身质量过得去，就是销售那套话术太夸张，容易劝退。', '[]', '2025-07-12T16:51:12+08:00');
